begin;
select no_plan();
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select public.approve_calendar('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',1);
select public.save_copy('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',1,'{"subject":"Original considered note","preheader":"Synthetic","body":"Explore the details at your own pace.","cta":"Explore","url":"https://cedar-lane.example"}');
select public.approve_copy('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',2);
set local role authenticated;
select throws_ok($$select public.escalate_design('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',2,'blocked','Original workflow issue')$$,'42501','Platform operator required','owner cannot operate platform design escalation');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.escalate_design('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',1,'blocked','Original workflow issue')$$,'PT409','Design workflow changed; refresh','stale admin workflow version rejected');
select throws_ok($$select public.escalate_design('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',2,'sla_overdue','Original workflow issue')$$,'23514','An overdue active designer SLA is required','no assignment cannot be mislabeled overdue');
select set_config('test.escalation',public.escalate_design('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',2,'no_designer','No permitted designer available in this synthetic proof')::text,true);
select is(public.escalate_design('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',2,'no_designer','No permitted designer available in this synthetic proof'),current_setting('test.escalation')::uuid,'replayed administrative issue retains one active event');
select is((select issue_state from public.design_escalation_operations()),'open','operator sees persisted open escalation');
select public.resolve_design_escalation('00000000-0000-4000-8000-000000000101',current_setting('test.escalation')::uuid,'Permitted designer assigned through the normal assignment workflow.');
select public.resolve_design_escalation('00000000-0000-4000-8000-000000000101',current_setting('test.escalation')::uuid,'Permitted designer assigned through the normal assignment workflow.');
select is((select issue_state from public.design_escalation_operations()),'resolved','resolution persists and replays safely');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select is((select count(*) from public.campaign_events where action='design_escalation_resolved'),1::bigint,'resolution history is unique and visible to the owner');
select is((select copy_state from public.campaigns where id='00000000-0000-4000-8000-000000000601'),'approved','administrative resolution preserves creative copy approval');
select is((select design_state from public.campaigns where id='00000000-0000-4000-8000-000000000601'),'unassigned','administrative resolution never approves a design');
select throws_ok($$select public.resolve_design_escalation('00000000-0000-4000-8000-000000000101',current_setting('test.escalation')::uuid,'Original unauthorized resolution')$$,'42501','Platform operator required','owner cannot resolve the platform issue');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select is((select count(*) from public.design_escalation_operations()),0::bigint,'designer cannot enumerate unrelated operator escalations');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
-- RET-001 revoked assign_campaign from signed-in users; set up as the owner role.
reset role;
select public.assign_campaign('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',(select id from public.assignable_designers('00000000-0000-4000-8000-000000000101') limit 1),2);
set local role authenticated;
select throws_ok($$select public.escalate_design('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',3,'no_designer','Original workflow issue')$$,'23514','Active assignment already exists','active assignment cannot be mislabeled unavailable');
select throws_ok($$select public.escalate_design('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',3,'sla_overdue','Original workflow issue')$$,'23514','An overdue active designer SLA is required','future SLA cannot be escalated as overdue');
reset role;
update public.designer_assignments set due_at=now()-interval '1 minute';
set local role authenticated;
select lives_ok($$select public.escalate_design('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',3,'sla_overdue','Original overdue designer workflow issue')$$,'operator persists a verified overdue assignment issue');
select ok((select sla_overdue from public.design_escalation_operations()),'overdue marker derives from active persisted assignment');
select * from finish();rollback;
